import { cache } from "react";

import type { ApiResponse, FileRef, PaginatedResponse } from "@repo/shared/types";

// Public contact reads and writes for clients with no signed-in user.
//
// Generated by grit with --public, and not overwritten when the resource is
// regenerated: the Go side's allowlist is yours to edit, and this file is typed
// against it.
//
// These call /public/contacts, not the authenticated routes the hooks in
// hooks/use-contacts.ts call. The authenticated ones answer 401
// without a session, which is correct for the admin panel and useless here.

const API_URL = (
  process.env.API_INTERNAL_URL ||
  process.env.NEXT_PUBLIC_API_URL ||
  "http://localhost:8080"
).replace(/\/+$/, "");

// Publishable by design: it reaches the public directory, including its CRUD
// operations. Protected admin endpoints still require a signed-in user.
const API_KEY = process.env.NEXT_PUBLIC_API_KEY ?? "";

// PublicContact is the published shape: the allowlist in
// internal/handlers/contact_public.go, not the model. Add a field
// there and add it here.
export interface PublicContact {
  id: string;
  name: string;
  email: string;
  phone: string;
  profile: FileRef | null;
  version?: number;
}

export type PublicContactPage = {
  data: PublicContact[];
  meta: PaginatedResponse<PublicContact>["meta"] | undefined;
};

async function publicGet<T>(path: string): Promise<{ status: number; body: T | null }> {
  try {
    const res = await fetch(API_URL + path, {
      headers: API_KEY ? { "X-API-Key": API_KEY } : {},
      cache: "no-store",
    });
    if (!res.ok) return { status: res.status, body: null };
    return { status: res.status, body: (await res.json()) as T };
  } catch {
    // Callers distinguish a network failure from an empty list or missing row.
    return { status: 0, body: null };
  }
}

// One page of contacts. Every search, sort, filter and range the
// public handler allows is a query parameter; anything it does not allow is
// ignored rather than rejected.
export const getPublicContacts = cache(
  async (params: Record<string, string | number | undefined> = {}): Promise<PublicContactPage> => {
    const query = new URLSearchParams();
    for (const [key, value] of Object.entries(params)) {
      if (value !== undefined && value !== "") query.set(key, String(value));
    }
    const suffix = query.toString() ? "?" + query.toString() : "";
    const { body } = await publicGet<PaginatedResponse<PublicContact>>(
      "/api/v1/public/contacts" + suffix
    );
    if (!body) throw new Error("Unable to load contacts. Please try again.");
    return { data: body.data, meta: body.meta };
  }
);

// One contact by its public key, or null when there is none.
//
// A row that is archived or switched off is a 404 here, the same as one that
// never existed: whether it exists is itself not public. An API that fails is
// an error rather than a missing row, so it is not reported as null.
export const getPublicContact = cache(async (key: string): Promise<PublicContact | null> => {
  const { status, body } = await publicGet<{ data: PublicContact }>(
    "/api/v1/public/contacts/" + encodeURIComponent(key)
  );
  if (status === 404) return null;
  if (!body)
    throw new Error("the public contact API answered " + (status || "nothing") + " for " + key);
  return body.data;
});
export async function publicCreate<TResource, TRequestData = unknown>(
  path: string,
  data: TRequestData,
  method: "POST" | "PUT" = "POST",
  version?: number
): Promise<{
  status: number;
  body: TResource | null;
  message?: string;
}> {
  try {
    const endpoint = `${API_URL}${path}`;
    const res = await fetch(endpoint, {
      method,
      headers: {
        "Content-Type": "application/json",
        ...(version ? { "If-Match": String(version) } : {}),
        ...(API_KEY
          ? {
              "X-API-Key": API_KEY,
            }
          : {}),
      },
      body: JSON.stringify(data),
    });
    if (!res.ok) {
      const error = await res.json().catch(() => null);
      return {
        status: res.status,
        body: null,
        message: error?.error?.message ?? "Failed to create contact. Please try again.",
      };
    }
    const result = (await res.json()) as ApiResponse<TResource>;
    return {
      status: res.status,
      body: result.data,
      message: result.message,
    };
  } catch {
    return {
      status: 500,
      body: null,
      message: "Unable to reach the API. Please try again.",
    };
  }
}

export async function deletePublicContact(id: string): Promise<void> {
  const res = await fetch(`${API_URL}/api/v1/public/contacts/${encodeURIComponent(id)}`, {
    method: "DELETE",
    headers: API_KEY ? { "X-API-Key": API_KEY } : {},
  });
  if (!res.ok) {
    const body = await res.json().catch(() => null);
    throw new Error(body?.error?.message ?? "Unable to delete contact. Please try again.");
  }
}
